// Default birthday used for Life Path and Personal Year/Month. Set
// BIRTHDAY=YYYY-MM-DD when building, or put it in uebersicht/birthday.txt
// (gitignored). MM-DD still works for personal cycles, but Life Path needs the
// year. The in-widget form stores an override in localStorage.
const BIRTHDAY = "";

const BIRTHDAY_KEY = 'daily-energy-birthday';

const readStoredBirthday = () => {
  try {
    return localStorage.getItem(BIRTHDAY_KEY);
  } catch {
    return null;
  }
};

/** Accept YYYY-MM-DD or legacy MM-DD. Full dates are normalized and padded. */
const normalizeBirthday = (value) => {
  const trimmed = String(value).trim();
  if (/^\d{4}-\d{1,2}-\d{1,2}$/.test(trimmed)) {
    const { year, month, day } = NumerologyCore.parseBirthDateInput(trimmed);
    return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
  }
  const { month, day } = NumerologyCore.parseBirthdayInput(trimmed);
  return `${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
};

/** The in-widget form requires the full date so Life Path always works. */
const normalizeFullBirthday = (value) => {
  const { year, month, day } = NumerologyCore.parseBirthDateInput(String(value).trim());
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
};

const formatBirthday = (value) => normalizeBirthday(value);

const initialBirthday = (() => {
  const value = readStoredBirthday() || BIRTHDAY;
  if (!value) return null;
  try {
    return normalizeBirthday(value);
  } catch {
    return null;
  }
})();

const GOLD = '#d4af37';
const GOLD_LIGHT = '#e8c56d';
const BRONZE = '#cd7f32';
const PAPER = '#efe6cf';
const MUTED = '#9a907a';
const RULE = 'rgba(212, 175, 55, 0.22)';

const SERIF = "'Iowan Old Style', 'Palatino Linotype', 'Book Antiqua', Palatino, Georgia, serif";
const MONO = "'SF Mono', Menlo, Monaco, 'Courier New', monospace";

export const command = 'date +%s';
export const refreshFrequency = 60000;

export const initialState = {
  output: '',
  error: null,
  birthday: initialBirthday,
  editing: false,
  draft: '',
  formError: null
};

export const updateState = (event, previousState) => {
  switch (event.type) {
    case 'BIRTHDAY_EDIT':
      return {
        ...previousState,
        editing: true,
        draft: previousState.birthday || '',
        formError: null
      };
    case 'BIRTHDAY_DRAFT':
      return { ...previousState, draft: event.value, formError: null };
    case 'BIRTHDAY_CANCEL':
      return { ...previousState, editing: false, draft: '', formError: null };
    case 'BIRTHDAY_SAVE': {
      const value = String(event.value ?? previousState.draft ?? '').trim();

      if (!value) {
        return {
          ...previousState,
          formError: 'Use YYYY-MM-DD, for example 2003-05-23'
        };
      }

      try {
        const normalized = normalizeFullBirthday(value);
        try {
          localStorage.setItem(BIRTHDAY_KEY, normalized);
        } catch {
          // Keep the in-memory value even if persistence is unavailable.
        }
        return {
          ...previousState,
          birthday: normalized,
          editing: false,
          draft: '',
          formError: null
        };
      } catch {
        return {
          ...previousState,
          formError: 'Use YYYY-MM-DD, for example 2003-05-23'
        };
      }
    }
    default:
      if (event.error) {
        return { ...previousState, error: event.error };
      }
      return {
        ...previousState,
        output: event.output !== undefined ? event.output : previousState.output,
        error: null
      };
  }
};

